$result = array();
$jumlah = 0;
$log = array();

while($record = $button->getNextSelectedRecord())
{
    $npsn  = trim($record["npsn"]);
    $tahap = trim($record["tahap"]);
    $tahun = trim($record["tahun"]);

    if ($npsn == "" || $tahap == "" || $tahun == "")
    {
        continue;
    }

    $sql = DB::PrepareSQL(
        "UPDATE data_sibay
         SET kunci_kemenag_pidie = 'selesai'
         WHERE npsn = ':1' AND tahap = ':2' AND tahun = ':3'",
        $npsn, $tahap, $tahun
    );
    DB::Exec($sql);

    $log[] = $npsn . " (tahap " . $tahap . ")";
    $jumlah++;
}

$result["jumlah"] = $jumlah;
$result["log"] = implode("\n", $log);
